public class DiamondDrawerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage img =
                    new java.awt.image.BufferedImage(200, 200, java.awt.image.BufferedImage.TYPE_INT_RGB);
            java.awt.Graphics2D g = img.createGraphics();
            try {
                DiamondDrawer.paint(g, 200);
            } finally {
                g.dispose();
            }
            check("center is red (100,100)", "#FF0000", pixel(img, 100, 100));
            check("above center, inside the diamond (100,78)", "#FF0000", pixel(img, 100, 78));
            check("right of center, inside the diamond (120,100)", "#FF0000", pixel(img, 120, 100));
            check("unrotated square's top-left corner area is white (75,75)", "#FFFFFF", pixel(img, 75, 75));
            check("unrotated square's top-right corner area is white (125,75)", "#FFFFFF", pixel(img, 125, 75));
            check("unrotated square's bottom-left corner area is white (75,125)", "#FFFFFF", pixel(img, 75, 125));
            check("unrotated square's bottom-right corner area is white (125,125)", "#FFFFFF", pixel(img, 125, 125));
            check("background corner is white (10,10)", "#FFFFFF", pixel(img, 10, 10));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

